-- Trang "Chép câu": thêm thư mục "2.1. Cho phép, giúp đỡ, khuyến khích" gồm 100 câu luyện dịch Việt → Anh,
-- mỗi câu dùng 1 pattern ở mục 2.1 của DATA/huong-dan-song-ngu.html.
-- Chạy trong Supabase → SQL Editor. An toàn khi chạy lại: đã có thư mục cùng tên thì bỏ qua.

do $$
declare
  -- Email đăng nhập app. Để trống = tự lấy tài khoản có thư mục "01. ..." (bộ 01–15 hiện có).
  v_email  text := '';
  v_name   text := '2.1. Cho phép, giúp đỡ, khuyến khích';
  v_user   uuid;
  v_count  int;
  v_folder uuid;
  v_now    timestamptz := now();
begin
  if v_email <> '' then
    select id into v_user from auth.users where lower(email) = lower(v_email);
    if v_user is null then
      raise exception 'Không có tài khoản nào với email %', v_email;
    end if;
  else
    select count(distinct user_id), min(user_id::text)::uuid into v_count, v_user
    from public.sentence_folders
    where name like '01.%' and deleted_at is null;
    if v_count <> 1 then
      raise exception 'Tìm thấy % tài khoản có thư mục "01. ...". Hãy điền v_email ở đầu script.', v_count;
    end if;
  end if;

  if exists (
    select 1 from public.sentence_folders
    where user_id = v_user and name = v_name and deleted_at is null
  ) then
    raise notice 'Thư mục "%" đã có, bỏ qua.', v_name;
    return;
  end if;

  insert into public.sentence_folders (user_id, name)
  values (v_user, v_name)
  returning id into v_folder;

  -- App xếp câu theo created_at: cách nhau 1 ms để giữ đúng thứ tự 1 → 100
  insert into public.sentences
    (user_id, folder_id, vi, en, alt_answers, hints, level, topic, created_at, updated_at)
  select v_user, v_folder, s.vi, s.en, s.alt, s.hints, s.level, s.topic,
         v_now + s.n * interval '1 millisecond', v_now + s.n * interval '1 millisecond'
  from (values
    (1, 'Làm việc từ xa cho phép nhân viên dành nhiều thời gian hơn cho gia đình.', 'Remote working allows employees to spend more time with their families.', '["Remote work allows employees to spend more time with their families.","Working from home allows employees to spend more time with their families."]'::jsonb, '["allow sb to do sth = cho phép ai làm gì","spend time with sb = dành thời gian cho ai"]'::jsonb, 'B1', 'allow sb to do sth'),
    (2, 'Điện thoại thông minh cho phép mọi người đọc tin tức ở bất cứ đâu.', 'Smartphones allow people to read the news anywhere.', '["Smartphones allow people to read news anywhere.","Smartphones allow people to read the news wherever they are."]'::jsonb, '["allow sb to do sth = cho phép ai làm gì","anywhere = ở bất cứ đâu"]'::jsonb, 'B1', 'allow sb to do sth'),
    (3, 'Một số trường học không cho phép học sinh dùng điện thoại trong lớp.', 'Some schools do not allow students to use their phones in class.', '["Some schools don''t allow students to use their phones in class.","Some schools do not allow students to use phones in class."]'::jsonb, '["allow sb to do sth = cho phép ai làm gì","phủ định: do not allow sb to do sth"]'::jsonb, 'B1', 'allow sb to do sth'),
    (4, 'Các khóa học trực tuyến cho phép người đi làm học vào buổi tối.', 'Online courses allow working adults to study in the evening.', '["Online courses allow working people to study in the evening.","Online courses allow workers to study in the evening."]'::jsonb, '["allow sb to do sth = cho phép ai làm gì","working adults = người đi làm"]'::jsonb, 'B1', 'allow sb to do sth'),
    (5, 'Chính phủ nên cho phép người dân tham gia vào các quyết định quan trọng.', 'The government should allow citizens to take part in important decisions.', '["The government should allow citizens to participate in important decisions.","Governments should allow citizens to take part in important decisions."]'::jsonb, '["allow sb to do sth = cho phép ai làm gì","take part in = participate in = tham gia vào"]'::jsonb, 'B1', 'allow sb to do sth'),
    (6, 'Giờ làm việc linh hoạt cho phép cha mẹ đón con sau giờ học.', 'Flexible working hours allow parents to pick up their children after school.', '["Flexible working hours allow parents to pick their children up after school.","Flexible hours allow parents to pick up their children after school."]'::jsonb, '["allow sb to do sth = cho phép ai làm gì","pick up sb = đón ai"]'::jsonb, 'B1', 'allow sb to do sth'),
    (7, 'Phương tiện công cộng cho phép người dân đi lại mà không cần ô tô riêng.', 'Public transport allows people to travel without a private car.', '["Public transport allows people to get around without a private car.","Public transport allows residents to travel without a private car."]'::jsonb, '["allow sb to do sth = cho phép ai làm gì","without + N = mà không cần"]'::jsonb, 'B1', 'allow sb to do sth'),
    (8, 'Du lịch nước ngoài cho phép người trẻ trải nghiệm những nền văn hóa khác nhau.', 'Travelling abroad allows young people to experience different cultures.', '["Traveling abroad allows young people to experience different cultures.","Travelling overseas allows young people to experience different cultures."]'::jsonb, '["allow sb to do sth = cho phép ai làm gì","experience (v) = trải nghiệm"]'::jsonb, 'B1', 'allow sb to do sth'),
    (9, 'Mạng xã hội cho phép các doanh nghiệp nhỏ tiếp cận khách hàng mới.', 'Social media allows small businesses to reach new customers.', '["Social networks allow small businesses to reach new customers.","Social media allows small companies to reach new customers."]'::jsonb, '["allow sb to do sth = cho phép ai làm gì","reach customers = tiếp cận khách hàng"]'::jsonb, 'B1', 'allow sb to do sth'),
    (10, 'Thư viện công cộng cho phép mọi người mượn sách miễn phí.', 'Public libraries allow people to borrow books for free.', '["Public libraries allow everyone to borrow books for free.","Public libraries allow people to borrow books free of charge."]'::jsonb, '["allow sb to do sth = cho phép ai làm gì","for free = free of charge = miễn phí"]'::jsonb, 'B1', 'allow sb to do sth'),
    (11, 'Bố mẹ tôi để tôi đi du lịch một mình khi tôi mười tám tuổi.', 'My parents let me travel alone when I was eighteen.', '["My parents let me travel on my own when I was eighteen.","My parents let me travel alone when I was 18."]'::jsonb, '["let sb do sth = để ai làm gì (thân mật)","let + O + V nguyên mẫu (không có to)"]'::jsonb, 'B1', 'let sb do sth'),
    (12, 'Nhiều cha mẹ để con cái chơi điện tử hàng giờ liền.', 'Many parents let their children play video games for hours.', '["Many parents let their kids play video games for hours.","Many parents let their children play computer games for hours."]'::jsonb, '["let sb do sth = để ai làm gì (thân mật)","for hours = hàng giờ liền"]'::jsonb, 'B1', 'let sb do sth'),
    (13, 'Sếp của tôi để tôi làm việc ở nhà vào thứ Sáu.', 'My boss lets me work from home on Fridays.', '["My boss lets me work at home on Fridays.","My manager lets me work from home on Fridays."]'::jsonb, '["let sb do sth = để ai làm gì (thân mật)","chủ ngữ số ít: lets"]'::jsonb, 'B1', 'let sb do sth'),
    (14, 'Giáo viên nên để học sinh tự chọn chủ đề cho bài thuyết trình.', 'Teachers should let students choose their own topics for presentations.', '["Teachers should let students choose their own presentation topics.","Teachers should let students choose the topics for their presentations."]'::jsonb, '["let sb do sth = để ai làm gì (thân mật)","choose one''s own sth = tự chọn"]'::jsonb, 'B1', 'let sb do sth'),
    (15, 'Đừng để trẻ em dùng mạng xã hội trước tuổi mười ba.', 'Do not let children use social media before the age of thirteen.', '["Don''t let children use social media before the age of thirteen.","Don''t let children use social media before the age of 13.","Do not let children use social media before the age of 13."]'::jsonb, '["let sb do sth = để ai làm gì (thân mật)","before the age of = trước tuổi"]'::jsonb, 'B1', 'let sb do sth'),
    (16, 'Bạn cùng phòng để tôi mượn xe đạp của cô ấy mỗi cuối tuần.', 'My roommate lets me borrow her bike every weekend.', '["My roommate lets me borrow her bicycle every weekend.","My flatmate lets me borrow her bike every weekend."]'::jsonb, '["let sb do sth = để ai làm gì (thân mật)","borrow = mượn"]'::jsonb, 'B1', 'let sb do sth'),
    (17, 'Ứng dụng này để người dùng tải video miễn phí.', 'This app lets users download videos for free.', '["This application lets users download videos for free.","This app lets users download videos free of charge."]'::jsonb, '["let sb do sth = để ai làm gì (thân mật)","download = tải về"]'::jsonb, 'B1', 'let sb do sth'),
    (18, 'Hồi nhỏ, mẹ tôi để tôi phụ mẹ nấu bữa tối.', 'When I was a child, my mother let me help her cook dinner.', '["When I was a child, my mom let me help her cook dinner.","When I was little, my mother let me help her cook dinner.","When I was young, my mother let me help her cook dinner."]'::jsonb, '["let sb do sth = để ai làm gì (thân mật)","quá khứ của let vẫn là let"]'::jsonb, 'B1', 'let sb do sth'),
    (19, 'Một số công ty để nhân viên tự chọn giờ làm việc.', 'Some companies let employees choose their own working hours.', '["Some companies let their employees choose their own working hours.","Some companies let staff choose their own working hours."]'::jsonb, '["let sb do sth = để ai làm gì (thân mật)","working hours = giờ làm việc"]'::jsonb, 'B1', 'let sb do sth'),
    (20, 'Tập thể dục đều đặn giúp người lớn tuổi ngủ ngon hơn.', 'Regular exercise helps older people sleep better.', '["Regular exercise helps older people to sleep better.","Regular exercise helps elderly people sleep better.","Regular exercise helps the elderly sleep better."]'::jsonb, '["help sb (to) do sth = giúp ai làm gì","sleep better = ngủ ngon hơn"]'::jsonb, 'B1', 'help sb (to) do sth'),
    (21, 'Đọc sách mỗi ngày giúp trẻ em mở rộng vốn từ vựng.', 'Reading every day helps children expand their vocabulary.', '["Reading every day helps children to expand their vocabulary.","Reading every day helps children build their vocabulary.","Reading daily helps children expand their vocabulary."]'::jsonb, '["help sb (to) do sth = giúp ai làm gì","expand one''s vocabulary = mở rộng vốn từ"]'::jsonb, 'B1', 'help sb (to) do sth'),
    (22, 'Làm việc nhóm giúp học sinh học cách hợp tác với người khác.', 'Group work helps students learn how to cooperate with others.', '["Group work helps students to learn how to cooperate with others.","Teamwork helps students learn how to cooperate with others.","Group work helps students learn to cooperate with others."]'::jsonb, '["help sb (to) do sth = giúp ai làm gì","cooperate with sb = hợp tác với ai"]'::jsonb, 'B1', 'help sb (to) do sth'),
    (23, 'Công việc làm thêm giúp sinh viên trang trải học phí.', 'Part-time jobs help students pay their tuition fees.', '["Part-time jobs help students to pay their tuition fees.","Part-time jobs help students cover their tuition fees.","Part-time jobs help students pay for their tuition."]'::jsonb, '["help sb (to) do sth = giúp ai làm gì","tuition fees = học phí"]'::jsonb, 'B1', 'help sb (to) do sth'),
    (24, 'Ứng dụng bản đồ giúp khách du lịch tìm đường ở những thành phố xa lạ.', 'Map apps help tourists find their way in unfamiliar cities.', '["Map apps help tourists to find their way in unfamiliar cities.","Map applications help tourists find their way in unfamiliar cities.","Map apps help tourists find their way in new cities."]'::jsonb, '["help sb (to) do sth = giúp ai làm gì","find one''s way = tìm đường"]'::jsonb, 'B1', 'help sb (to) do sth'),
    (25, 'Thuế thuốc lá cao có thể giúp người hút thuốc bỏ thói quen này.', 'High taxes on cigarettes can help smokers give up this habit.', '["High taxes on cigarettes can help smokers to give up this habit.","High cigarette taxes can help smokers give up this habit.","High taxes on cigarettes can help smokers quit this habit."]'::jsonb, '["help sb (to) do sth = giúp ai làm gì","give up = quit = từ bỏ"]'::jsonb, 'B1', 'help sb (to) do sth'),
    (26, 'Tình nguyện viên giúp người già trong làng sử dụng điện thoại thông minh.', 'Volunteers help elderly villagers use smartphones.', '["Volunteers help elderly villagers to use smartphones.","Volunteers help old people in the village use smartphones.","Volunteers help elderly people in the village use smartphones."]'::jsonb, '["help sb (to) do sth = giúp ai làm gì","villagers = người dân trong làng"]'::jsonb, 'B1', 'help sb (to) do sth'),
    (27, 'Học ngoại ngữ giúp người trẻ tìm được việc làm tốt hơn.', 'Learning a foreign language helps young people find better jobs.', '["Learning a foreign language helps young people to find better jobs.","Learning foreign languages helps young people find better jobs."]'::jsonb, '["help sb (to) do sth = giúp ai làm gì","V-ing làm chủ ngữ: Learning ... helps"]'::jsonb, 'B1', 'help sb (to) do sth'),
    (28, 'Ăn nhiều rau xanh giúp cơ thể chống lại bệnh tật.', 'Eating plenty of green vegetables helps the body fight disease.', '["Eating plenty of green vegetables helps the body to fight disease.","Eating plenty of vegetables helps the body fight disease.","Eating lots of green vegetables helps the body fight disease.","Eating more green vegetables helps the body fight diseases."]'::jsonb, '["help sb (to) do sth = giúp ai làm gì","fight disease = chống lại bệnh tật"]'::jsonb, 'B1', 'help sb (to) do sth'),
    (29, 'Giáo viên nên khuyến khích học sinh đặt câu hỏi trong lớp.', 'Teachers should encourage students to ask questions in class.', '["Teachers should encourage their students to ask questions in class.","Teachers should encourage pupils to ask questions in class."]'::jsonb, '["encourage sb to do sth = khuyến khích ai làm gì","ask questions = đặt câu hỏi"]'::jsonb, 'B1', 'encourage sb to do sth'),
    (30, 'Làn đường dành cho xe đạp khuyến khích người dân đạp xe đi làm.', 'Cycle lanes encourage people to cycle to work.', '["Bike lanes encourage people to cycle to work.","Cycle lanes encourage residents to cycle to work.","Bike lanes encourage people to ride bikes to work."]'::jsonb, '["encourage sb to do sth = khuyến khích ai làm gì","cycle lanes = làn xe đạp"]'::jsonb, 'B1', 'encourage sb to do sth'),
    (31, 'Chính phủ nên khuyến khích các hộ gia đình tái chế rác thải.', 'The government should encourage households to recycle their waste.', '["The government should encourage households to recycle waste.","The government should encourage families to recycle their waste.","Governments should encourage households to recycle their waste."]'::jsonb, '["encourage sb to do sth = khuyến khích ai làm gì","households = hộ gia đình"]'::jsonb, 'B1', 'encourage sb to do sth'),
    (32, 'Cha mẹ nên khuyến khích con cái chơi thể thao ngoài trời.', 'Parents should encourage their children to play outdoor sports.', '["Parents should encourage their children to play sports outdoors.","Parents should encourage children to play outdoor sports."]'::jsonb, '["encourage sb to do sth = khuyến khích ai làm gì","outdoor sports = thể thao ngoài trời"]'::jsonb, 'B1', 'encourage sb to do sth'),
    (33, 'Mức lương cao hơn sẽ khuyến khích nhiều người trẻ trở thành giáo viên hơn.', 'Higher salaries will encourage more young people to become teachers.', '["Higher salaries would encourage more young people to become teachers.","Better salaries will encourage more young people to become teachers."]'::jsonb, '["encourage sb to do sth = khuyến khích ai làm gì","more + N = nhiều ... hơn"]'::jsonb, 'B1', 'encourage sb to do sth'),
    (34, 'Các chương trình giảm giá khuyến khích khách hàng mua nhiều hơn mức cần thiết.', 'Discount programmes encourage customers to buy more than they need.', '["Discount programs encourage customers to buy more than they need.","Discount schemes encourage customers to buy more than they need.","Discounts encourage customers to buy more than necessary."]'::jsonb, '["encourage sb to do sth = khuyến khích ai làm gì","more than they need = nhiều hơn mức cần"]'::jsonb, 'B1', 'encourage sb to do sth'),
    (35, 'Các công ty nên khuyến khích nhân viên nghỉ giải lao ngắn.', 'Companies should encourage employees to take short breaks.', '["Companies should encourage their employees to take short breaks.","Companies should encourage staff to take short breaks."]'::jsonb, '["encourage sb to do sth = khuyến khích ai làm gì","take a break = nghỉ giải lao"]'::jsonb, 'B1', 'encourage sb to do sth'),
    (36, 'Học bổng khuyến khích học sinh nghèo tiếp tục việc học.', 'Scholarships encourage poor students to continue their studies.', '["Scholarships encourage poor students to continue studying.","Scholarships encourage disadvantaged students to continue their studies.","Scholarships encourage students from poor families to continue their studies."]'::jsonb, '["encourage sb to do sth = khuyến khích ai làm gì","continue one''s studies = tiếp tục việc học"]'::jsonb, 'B1', 'encourage sb to do sth'),
    (37, 'Bạn bè đã khuyến khích tôi tham gia cuộc thi hùng biện tiếng Anh.', 'My friends encouraged me to take part in an English speaking contest.', '["My friends encouraged me to enter an English speaking contest.","My friends encouraged me to join an English speaking contest.","My friends encouraged me to take part in an English speaking competition."]'::jsonb, '["encourage sb to do sth = khuyến khích ai làm gì","speaking contest = cuộc thi hùng biện"]'::jsonb, 'B1', 'encourage sb to do sth'),
    (38, 'Công nghệ y tế hiện đại giúp bác sĩ có khả năng phát hiện bệnh sớm hơn.', 'Modern medical technology enables doctors to detect diseases earlier.', '["Modern medical technology enables doctors to detect disease earlier.","Modern medical technology enables doctors to detect illnesses earlier.","Modern medical technology enables doctors to diagnose diseases earlier."]'::jsonb, '["enable sb to do sth = giúp ai có khả năng làm gì","detect = phát hiện"]'::jsonb, 'B2', 'enable sb to do sth'),
    (39, 'Internet tốc độ cao giúp các công ty có khả năng tuyển nhân viên từ nước khác.', 'High-speed Internet enables companies to hire staff from other countries.', '["High-speed Internet enables companies to recruit staff from other countries.","High-speed Internet enables companies to hire employees from other countries."]'::jsonb, '["enable sb to do sth = giúp ai có khả năng làm gì","hire / recruit staff = tuyển nhân viên"]'::jsonb, 'B2', 'enable sb to do sth'),
    (40, 'Năng lượng mặt trời giúp các cộng đồng vùng sâu vùng xa có khả năng tiếp cận điện.', 'Solar energy enables remote communities to access electricity.', '["Solar power enables remote communities to access electricity.","Solar energy enables remote communities to have access to electricity.","Solar energy enables remote areas to access electricity."]'::jsonb, '["enable sb to do sth = giúp ai có khả năng làm gì","remote communities = cộng đồng vùng sâu vùng xa"]'::jsonb, 'B2', 'enable sb to do sth'),
    (41, 'Kỹ năng tiếng Anh tốt giúp sinh viên có khả năng đọc tài liệu quốc tế.', 'Good English skills enable students to read international materials.', '["Good English skills enable students to read international documents.","Strong English skills enable students to read international materials.","Good English skills enable students to read international resources."]'::jsonb, '["enable sb to do sth = giúp ai có khả năng làm gì","materials = tài liệu"]'::jsonb, 'B2', 'enable sb to do sth'),
    (42, 'Các khoản vay lãi suất thấp giúp nông dân có khả năng mua máy móc hiện đại.', 'Low-interest loans enable farmers to buy modern machinery.', '["Low-interest loans enable farmers to purchase modern machinery.","Cheap loans enable farmers to buy modern machinery.","Low-interest loans enable farmers to buy modern machines."]'::jsonb, '["enable sb to do sth = giúp ai có khả năng làm gì","machinery = máy móc (danh từ không đếm được)"]'::jsonb, 'B2', 'enable sb to do sth'),
    (43, 'Hệ thống tàu điện ngầm giúp hàng triệu người có khả năng đi làm nhanh hơn.', 'The metro system enables millions of people to get to work faster.', '["The subway system enables millions of people to get to work faster.","The underground system enables millions of people to get to work faster.","The metro system enables millions of people to commute faster."]'::jsonb, '["enable sb to do sth = giúp ai có khả năng làm gì","get to work = đi làm"]'::jsonb, 'B2', 'enable sb to do sth'),
    (44, 'Học trực tuyến giúp học sinh nông thôn có khả năng học với giáo viên giỏi.', 'Online learning enables rural students to study with good teachers.', '["Online learning enables students in rural areas to study with good teachers.","Online learning enables rural students to learn from good teachers.","E-learning enables rural students to study with good teachers."]'::jsonb, '["enable sb to do sth = giúp ai có khả năng làm gì","rural students = học sinh nông thôn"]'::jsonb, 'B2', 'enable sb to do sth'),
    (45, 'Máy móc tự động giúp các nhà máy có khả năng sản xuất nhiều hàng hóa hơn.', 'Automated machines enable factories to produce more goods.', '["Automation enables factories to produce more goods.","Automatic machines enable factories to produce more goods.","Automated machines enable factories to manufacture more goods."]'::jsonb, '["enable sb to do sth = giúp ai có khả năng làm gì","goods = hàng hóa"]'::jsonb, 'B2', 'enable sb to do sth'),
    (46, 'Tiết kiệm từ sớm giúp người trẻ có khả năng mua nhà trong tương lai.', 'Saving early enables young people to buy a home in the future.', '["Saving early enables young people to buy a house in the future.","Saving money early enables young people to buy a home in the future.","Saving early enables young people to buy their own home in the future."]'::jsonb, '["enable sb to do sth = giúp ai có khả năng làm gì","V-ing làm chủ ngữ: Saving early ..."]'::jsonb, 'B2', 'enable sb to do sth'),
    (47, 'Mạng xã hội giúp mọi người có thể kết nối lại với bạn cũ.', 'Social media makes it possible for people to reconnect with old friends.', '["Social media has made it possible for people to reconnect with old friends.","Social networks make it possible for people to reconnect with old friends."]'::jsonb, '["make it possible for sb to do sth = giúp ai có thể làm gì","reconnect with sb = kết nối lại với ai"]'::jsonb, 'B2', 'make it possible for sb to do sth'),
    (48, 'Các hãng hàng không giá rẻ giúp sinh viên có thể đi du lịch nước ngoài.', 'Budget airlines make it possible for students to travel abroad.', '["Low-cost airlines make it possible for students to travel abroad.","Cheap airlines make it possible for students to travel abroad.","Budget airlines make it possible for students to travel overseas."]'::jsonb, '["make it possible for sb to do sth = giúp ai có thể làm gì","budget airlines = hãng bay giá rẻ"]'::jsonb, 'B2', 'make it possible for sb to do sth'),
    (49, 'Dịch vụ giao hàng giúp người già có thể mua sắm mà không cần ra khỏi nhà.', 'Delivery services make it possible for elderly people to shop without leaving home.', '["Delivery services make it possible for older people to shop without leaving home.","Delivery services make it possible for the elderly to shop without leaving home.","Delivery services make it possible for elderly people to shop without leaving their homes."]'::jsonb, '["make it possible for sb to do sth = giúp ai có thể làm gì","without + V-ing = mà không cần"]'::jsonb, 'B2', 'make it possible for sb to do sth'),
